const out = $input.first().json || {};

if (out.broker !== 'supabase') {
  throw new Error(`GTM 09 expected supabase broker, got ${out.broker}`);
}
if (out.broker_version !== 'SB-BROKER-V3.0.0') {
  throw new Error(`GTM 09 expected SB-BROKER-V3.0.0, got ${out.broker_version}`);
}
if (out.rpc_name !== 'gtm_project01_qa_report_v1') {
  throw new Error(`GTM 09 QA preflight RPC mismatch: ${out.rpc_name}`);
}

const report = Array.isArray(out.response) && out.response.length
  ? out.response[0]
  : null;

if (!report || typeof report !== 'object') {
  throw new Error('GTM 09 QA preflight missing report');
}

if (report.all_checks_pass !== true) {
  throw new Error('GTM 09 QA preflight reports project invariants are not green');
}

if (report.state !== 'PRE_SEND_CONTROLLED') {
  throw new Error(`GTM 09 expected PRE_SEND_CONTROLLED, got ${report.state}`);
}

return [{
  json: {
    gtm09_contract_dry_run_completed: true,
    supabase_broker_v3_passed: true,
    broker_workflow_id: 'SUPABASE_BROKER_V3_WORKFLOW_ID',
    production_entrypoint_configured: true,
    supported_event_families: ['provider_event', 'reply_event'],
    provider_event_rpc: 'gtm_ingest_outreach_provider_event_v1',
    reply_event_rpc: 'gtm_record_outreach_reply_v1',
    database_mutation_performed: false,
    provider_http_call_performed: false,
    credentials_required_in_parent: false,
    qa_state: report.state,
    qa_all_checks_pass: report.all_checks_pass,
    gtm09_dry_run_all_checks_pass: true
  }
}];

const input = $input.first().json || {};
const family = String(input.event_family || '').trim().toLowerCase();

if (!['provider_event', 'reply_event'].includes(family)) {
  throw new Error(`GTM 09 unsupported event_family: ${family}`);
}

const taskKey = String(input.task_key || '').trim();
if (!taskKey) {
  throw new Error('GTM 09 task_key is required');
}

if (family === 'provider_event') {
  const providerKey = String(input.provider_key || '').trim();
  const providerEventKey = String(input.provider_event_key || '').trim();
  const eventType = String(input.event_type || '').trim().toLowerCase();

  if (!providerKey) throw new Error('GTM 09 provider_key is required');
  if (!providerEventKey) throw new Error('GTM 09 provider_event_key is required');
  if (!eventType) throw new Error('GTM 09 event_type is required');

  const payload = input.payload ?? {};
  if (typeof payload !== 'object' || Array.isArray(payload)) {
    throw new Error('GTM 09 payload must be a JSON object');
  }

  return [{
    json: {
      route: 'provider_event',
      rpc_name: 'gtm_ingest_outreach_provider_event_v1',
      rpc_body: {
        p_provider_key: providerKey,
        p_provider_event_key: providerEventKey,
        p_provider_message_id: input.provider_message_id || null,
        p_task_key: taskKey,
        p_event_type: eventType,
        p_event_occurred_at: input.occurred_at || null,
        p_payload: payload
      }
    }
  }];
}

const replyEventKey = String(input.reply_event_key || '').trim();
const replyType = String(input.reply_type || '').trim().toLowerCase();

if (!replyEventKey) throw new Error('GTM 09 reply_event_key is required');
if (!replyType) throw new Error('GTM 09 reply_type is required');

const metadata = input.metadata ?? {};
if (typeof metadata !== 'object' || Array.isArray(metadata)) {
  throw new Error('GTM 09 metadata must be a JSON object');
}

return [{
  json: {
    route: 'reply_event',
    rpc_name: 'gtm_record_outreach_reply_v1',
    rpc_body: {
      p_reply_event_key: replyEventKey,
      p_task_key: taskKey,
      p_reply_type: replyType,
      p_reply_text: input.reply_text || null,
      p_occurred_at: input.occurred_at || null,
      p_metadata: metadata
    }
  }
}];

const out = $input.first().json || {};

if (out.broker !== 'supabase') {
  throw new Error(`GTM 09 expected supabase broker result`);
}
if (out.broker_version !== 'SB-BROKER-V3.0.0') {
  throw new Error(`GTM 09 unexpected broker version: ${out.broker_version}`);
}

const rows = Array.isArray(out.response) ? out.response : [];
if (rows.length !== 1) {
  throw new Error(`GTM 09 expected exactly one lifecycle result row, got ${rows.length}`);
}

return [{
  json: {
    gtm09_event_processed: true,
    rpc_name: out.rpc_name,
    broker_version: out.broker_version,
    result: rows[0],
    credentials_required_in_parent: false
  }
}];
